     9→import Combine
    10→import Foundation
    11→
    12→private enum SuggestionTriggerRegex {
    13→    /// Matches any string of characters after an @ or # that is not a whitespace
    14→    static let atOrHash = /[@#]\S*/
    15→    
    16→    static let at: Character = "@"
    17→    static let hash: Character = "#"
    18→}
    19→
    20→final class CompletionSuggestionService: CompletionSuggestionServiceProtocol {
    21→    private let roomProxy: JoinedRoomProxyProtocol
    22→    private var canMentionAllUsers = false
    23→    
    24→    private(set) var suggestionsPublisher: AnyPublisher<[SuggestionItem], Never> = Empty().eraseToAnyPublisher()
    25→    
    26→    private let suggestionTriggerSubject = CurrentValueSubject<SuggestionTrigger?, Never>(nil)
    27→    
    28→    private var cancellables = Set<AnyCancellable>()
    29→    
    30→    init(roomProxy: JoinedRoomProxyProtocol,
    31→         roomListPublisher: AnyPublisher<[RoomSummary], Never>) {
    32→        self.roomProxy = roomProxy
    33→        
    34→        suggestionsPublisher = suggestionTriggerSubject
    35→            .combineLatest(roomProxy.membersPublisher, roomListPublisher)
    36→            .map { [weak self, ownUserID = roomProxy.ownUserID] suggestionTrigger, members, roomSummaries -> [SuggestionItem] in
    37→                guard let self,
    38→                      let suggestionTrigger else {
    39→                    return []
    40→                }
    41→                
    42→                switch suggestionTrigger.type {
    43→                case .user:
    44→                    return membersSuggestions(suggestionTrigger: suggestionTrigger, members: members, ownUserID: ownUserID)
    45→                case .room:
    46→                    return roomSuggestions(suggestionTrigger: suggestionTrigger, roomSummaries: roomSummaries)
    47→                }
    48→            }
    49→            // We only debounce if the suggestion is nil
    50→            .debounceAndRemoveDuplicates(on: DispatchQueue.main) { [weak self] _ in
    51→                self?.suggestionTriggerSubject.value != nil ? .milliseconds(500) : .milliseconds(0)
    52→            }
    53→        
    54→        roomProxy.infoPublisher
    55→            .receive(on: DispatchQueue.main)
    56→            .sink { [weak self] roomInfo in
    57→                self?.updateRoomInfo(roomInfo)
    58→            }
    59→            .store(in: &cancellables)
    60→        
    61→        updateRoomInfo(roomProxy.infoPublisher.value)
    62→    }
    63→    
    64→    func processTextMessage(_ textMessage: String, selectedRange: NSRange) {
    65→        setSuggestionTrigger(detectTriggerInText(textMessage, selectedRange: selectedRange))
    66→    }
    67→    
    68→    func setSuggestionTrigger(_ suggestionTrigger: SuggestionTrigger?) {
    69→        suggestionTriggerSubject.value = suggestionTrigger
    70→    }
    71→    
    72→    // MARK: - Private
    73→    
    74→    private func updateRoomInfo(_ roomInfo: RoomInfoProxyProtocol) {
    75→        if let powerLevels = roomProxy.infoPublisher.value.powerLevels {
    76→            canMentionAllUsers = powerLevels.canOwnUserTriggerRoomNotification()
    77→        }
    78→    }
    79→    
    80→    private func membersSuggestions(suggestionTrigger: SuggestionTrigger,
    81→                                    members: [RoomMemberProxyProtocol],
    82→                                    ownUserID: String) -> [SuggestionItem] {
    83→        var membersSuggestion = members
    84→            .compactMap { member -> SuggestionItem? in
    85→                guard member.userID != ownUserID,
    86→                      member.membership == .join,
    87→                      Self.shouldIncludeMember(userID: member.userID, displayName: member.displayName, searchText: suggestionTrigger.text) else {
    88→                    return nil
    89→                }
    90→                return .init(suggestionType: .user(.init(id: member.userID, displayName: member.displayName, avatarURL: member.avatarURL)), range: suggestionTrigger.range, rawSuggestionText: suggestionTrigger.text)
    91→            }
    92→        
    93→        if canMentionAllUsers,
    94→           !roomProxy.isDirectOneToOneRoom,
    95→           Self.shouldIncludeMember(userID: PillUtilities.atRoom, displayName: PillUtilities.everyone, searchText: suggestionTrigger.text) {
    96→            membersSuggestion
    97→                .insert(SuggestionItem(suggestionType: .allUsers(roomProxy.details.avatar), range: suggestionTrigger.range, rawSuggestionText: suggestionTrigger.text), at: 0)
    98→        }
    99→        
   100→        return membersSuggestion
   101→    }
   102→    
   103→    private func roomSuggestions(suggestionTrigger: SuggestionTrigger,
   104→                                 roomSummaries: [RoomSummary]) -> [SuggestionItem] {
   105→        roomSummaries
   106→            .compactMap { roomSummary -> SuggestionItem? in
   107→                guard let canonicalAlias = roomSummary.canonicalAlias,
   108→                      Self.shouldIncludeRoom(roomName: roomSummary.name, roomAlias: canonicalAlias, searchText: suggestionTrigger.text) else {
   109→                    return nil
   110→                }
   111→                
   112→                return .init(suggestionType: .room(.init(id: roomSummary.id,
   113→                                                         canonicalAlias: canonicalAlias,
   114→                                                         name: roomSummary.name,
   115→                                                         avatar: roomSummary.avatar)),
   116→                             range: suggestionTrigger.range, rawSuggestionText: suggestionTrigger.text)
   117→            }
   118→    }
   119→    
   120→    private func detectTriggerInText(_ text: String, selectedRange: NSRange) -> SuggestionTrigger? {
   121→        let matches = text.matches(of: SuggestionTriggerRegex.atOrHash)
   122→        let match = matches.first { matchResult in
   123→            let lowerBound = matchResult.range.lowerBound.utf16Offset(in: matchResult.base)
   124→            let upperBound = matchResult.range.upperBound.utf16Offset(in: matchResult.base)
   125→            return selectedRange.location >= lowerBound
   126→                && selectedRange.location <= upperBound
   127→                && selectedRange.length <= upperBound - lowerBound
   128→        }
   129→
   130→        guard let match else {
   131→            return nil
   132→        }
   133→
   134→        var suggestionText = String(text[match.range])
   135→        let firstChar = suggestionText.removeFirst()
   136→        
   137→        switch firstChar {
   138→        case SuggestionTriggerRegex.at:
   139→            return .init(type: .user, text: suggestionText, range: NSRange(match.range, in: text))
   140→        case SuggestionTriggerRegex.hash:
   141→            return .init(type: .room, text: suggestionText, range: NSRange(match.range, in: text))
   142→        default:
   143→            return nil
   144→        }
   145→    }
   146→    
   147→    private static func shouldIncludeMember(userID: String, displayName: String?, searchText: String) -> Bool {
   148→        // If the search text is empty give back all the results
   149→        guard !searchText.isEmpty else {
   150→            return true
   151→        }
   152→        let containedInUserID = userID.localizedStandardContains(searchText)
   153→        
   154→        let containedInDisplayName: Bool
   155→        if let displayName {
   156→            containedInDisplayName = displayName.localizedStandardContains(searchText)
   157→        } else {
   158→            containedInDisplayName = false
   159→        }
   160→        
   161→        return containedInUserID || containedInDisplayName
   162→    }
   163→    
   164→    private static func shouldIncludeRoom(roomName: String, roomAlias: String, searchText: String) -> Bool {
   165→        // If the search text is empty give back all the results
   166→        guard !searchText.isEmpty else {
   167→            return true
   168→        }
   169→        return roomName.localizedStandardContains(searchText) || roomAlias.localizedStandardContains(searchText)
   170→    }
   171→}
