    13→struct SuggestionTrigger: Equatable {
    14→    enum SuggestionType: Equatable {
    15→        case user
    16→        case room
    17→    }
    18→    
    19→    let type: SuggestionType
    20→    let text: String
    21→    let range: NSRange
    22→}
    23→
    24→struct SuggestionItem: Identifiable, Equatable {
    25→    enum SuggestionType: Equatable {
    26→        case user(User)
    27→        case allUsers(RoomAvatar)
    28→        case room(Room)
    29→    }
    30→    
    31→    struct User: Equatable {
    32→        let id: String
    33→        let displayName: String?
    34→        let avatarURL: URL?
    35→    }
    36→    
    37→    struct Room: Equatable {
    38→        let id: String
    39→        let canonicalAlias: String
    40→        let name: String
    41→        let avatar: RoomAvatar
    42→    }
    43→    
    44→    let suggestionType: SuggestionType
    45→    let range: NSRange
    46→    let rawSuggestionText: String
    47→    
    48→    var id: String {
    49→        switch suggestionType {
    50→        case .user(let user):
    51→            user.id
    52→        case .allUsers:
    53→            PillUtilities.atRoom
    54→        case .room(let room):
    55→            room.id
    56→        }
    57→    }
    58→    
    59→    var displayName: String {
    60→        switch suggestionType {
    61→        case .allUsers:
    62→            return PillUtilities.everyone
    63→        case .user(let user):
    64→            return user.displayName ?? user.id
    65→        case .room(let room):
    66→            return room.name
    67→        }
    68→    }
    69→    
    70→    var subtitle: String? {
    71→        switch suggestionType {
    72→        case .allUsers:
    73→            return PillUtilities.atRoom
    74→        case .user(let user):
    75→            return user.displayName == nil ? nil : user.id
    76→        case .room(let room):
    77→            return room.canonicalAlias
    78→        }
    79→    }
    80→}
