   256→    func process(timelineAction: TimelineComposerAction) {
   257→        switch timelineAction {
   258→        case .setMode(mode: let mode):
   259→            if state.composerMode.isComposingNewMessage, mode.isEdit {
   260→                handleSaveDraft(isVolatile: true)
   261→            }
   262→            set(mode: mode)
   263→        case .setText(let plainText, let htmlText):
   264→            if let htmlText, context.composerFormattingEnabled {
   265→                set(text: htmlText)
   266→            } else {
   267→                set(text: plainText)
   268→            }
   269→        case .setFocus:
   270→            state.bindings.composerFocused = true
   271→        case .removeFocus:
   272→            state.bindings.composerFocused = false
   273→        case .clear:
   274→            if let draft = draftService.loadVolatileDraft() {
   275→                handleLoadDraft(draft)
   276→                draftService.clearVolatileDraft()
   277→            } else {
   278→                set(mode: .default)
   279→                set(text: "")
   280→            }
   281→        }
   282→    }
   283→    
   284→    func loadDraft() async {
   285→        if let initialText {
   286→            set(text: initialText)
   287→            set(mode: .default)
   288→            state.bindings.composerFocused = true
   289→        } else {
   290→            guard case let .success(draft) = await draftService.loadDraft(),
   291→                  let draft else {
   292→                return
   293→            }
   294→            handleLoadDraft(draft)
   295→        }
   296→    }
   297→    
   298→    func saveDraft() {
   299→        handleSaveDraft(isVolatile: false)
   300→    }
