   302→    // MARK: - Private
   303→    
   304→    private func handleLoadDraft(_ draft: ComposerDraftProxy) {
   305→        if let html = draft.htmlText {
   306→            context.composerFormattingEnabled = true
   307→            DispatchQueue.main.async {
   308→                self.set(text: html)
   309→            }
   310→        } else {
   311→            context.composerFormattingEnabled = false
   312→            set(text: draft.plainText)
   313→        }
   314→        
   315→        switch draft.draftType {
   316→        case .newMessage:
   317→            set(mode: .default)
   318→        case .edit(let eventID):
   319→            set(mode: .edit(originalEventOrTransactionID: .eventID(eventID), type: .default))
   320→        case .reply(let eventID):
   321→            set(mode: .reply(eventID: eventID, replyDetails: .loading(eventID: eventID), isThread: false))
   322→            replyLoadingTask = Task {
   323→                let reply = switch await draftService.getReply(eventID: eventID) {
   324→                case .success(let reply):
   325→                    reply
   326→                case .failure:
   327→                    TimelineItemReply(details: .error(eventID: eventID, message: L10n.commonSomethingWentWrong), isThreaded: false)
   328→                }
   329→                
   330→                guard !Task.isCancelled else {
   331→                    return
   332→                }
   333→                
   334→                set(mode: .reply(eventID: eventID, replyDetails: reply.details, isThread: reply.isThreaded))
   335→            }
   336→        }
   337→    }
   338→    
   339→    private func handleSaveDraft(isVolatile: Bool) {
   340→        let plainText: String
   341→        let htmlText: String?
   342→        let type: ComposerDraftProxy.ComposerDraftType
   343→        
   344→        if context.composerFormattingEnabled {
   345→            if wysiwygViewModel.isContentEmpty, state.composerMode == .default {
   346→                if isVolatile {
   347→                    draftService.clearVolatileDraft()
   348→                } else {
   349→                    Task {
   350→                        await draftService.clearDraft()
   351→                    }
   352→                }
   353→                return
   354→            }
   355→            plainText = wysiwygViewModel.content.markdown
   356→            htmlText = wysiwygViewModel.content.html
   357→        } else {
   358→            if context.plainComposerText.string.isEmpty, state.composerMode == .default {
   359→                if isVolatile {
   360→                    draftService.clearVolatileDraft()
   361→                } else {
   362→                    Task {
   363→                        await draftService.clearDraft()
   364→                    }
   365→                }
   366→                return
   367→            }
   368→            plainText = plainComposerContent.text
   369→            htmlText = nil
   370→        }
   371→        
   372→        switch state.composerMode {
   373→        case .default:
   374→            type = .newMessage
   375→        case .edit(.eventID(let originalEventID), .default):
   376→            type = .edit(eventID: originalEventID)
   377→        case .reply(let eventID, _, _):
   378→            type = .reply(eventID: eventID)
   379→        default:
   380→            if isVolatile {
   381→                draftService.clearVolatileDraft()
   382→            } else {
   383→                Task {
   384→                    await draftService.clearDraft()
   385→                }
   386→            }
   387→            return
   388→        }
   389→        
   390→        if isVolatile {
   391→            draftService.saveVolatileDraft(.init(plainText: plainText, htmlText: htmlText, draftType: type))
   392→        } else {
   393→            Task {
   394→                await draftService.saveDraft(.init(plainText: plainText, htmlText: htmlText, draftType: type))
   395→            }
   396→        }
   397→    }
