   399→    private var plainComposerContent: PlainComposerContent {
   400→        let attributedString = NSMutableAttributedString(attributedString: context.plainComposerText)
   401→
   402→        var shouldMakeAnotherPass = false
   403→        var userIDs = Set<String>()
   404→        var containsAtRoom = false
   405→        
   406→        repeat { // Don't enumerate and mutate at the same time, big no no
   407→            shouldMakeAnotherPass = false
   408→            attributedString.enumerateAttribute(.link, in: .init(location: 0, length: attributedString.length), options: []) { value, range, stop in
   409→                guard let value else { return }
   410→                shouldMakeAnotherPass = true
   411→                
   412→                // Remove the attribute so it doesn't get inherited by the new string
   413→                attributedString.removeAttribute(.link, range: range)
   414→                
   415→                if let userID = attributedString.attribute(.MatrixUserID, at: range.location, effectiveRange: nil) as? String {
   416→                    let displayName = attributedString.attribute(.MatrixUserDisplayName, at: range.location, effectiveRange: nil)
   417→                    attributedString.replaceCharacters(in: range, with: "[\(displayName ?? userID)](\(value))")
   418→                    userIDs.insert(userID)
   419→                    stop.pointee = true
   420→                } else if let roomAlias = attributedString.attribute(.MatrixRoomAlias, at: range.location, effectiveRange: nil) as? String {
   421→                    let displayName = attributedString.attribute(.MatrixRoomDisplayName, at: range.location, effectiveRange: nil)
   422→                    attributedString.replaceCharacters(in: range, with: "[\(displayName ?? roomAlias)](\(value))")
   423→                    stop.pointee = true
   424→                } else {
   425→                    return
   426→                }
   427→            }
   428→        } while shouldMakeAnotherPass
   429→        
   430→        repeat {
   431→            shouldMakeAnotherPass = false
   432→            attributedString.enumerateAttribute(.MatrixAllUsersMention, in: .init(location: 0, length: attributedString.length), options: []) { value, range, stop in
   433→                guard value != nil else { return }
   434→                
   435→                shouldMakeAnotherPass = true
   436→                
   437→                // Remove the attribute so it doesn't get inherited by the new string
   438→                attributedString.removeAttribute(.MatrixAllUsersMention, range: range)
   439→                
   440→                attributedString.replaceCharacters(in: range, with: PillUtilities.atRoom)
   441→                containsAtRoom = true
   442→                
   443→                stop.pointee = true
   444→            }
   445→        } while shouldMakeAnotherPass
   446→        
   447→        return .init(text: attributedString.string, mentionedUserIDs: userIDs, containsAtRoomMention: containsAtRoom)
   448→    }
