   616→    private func parseUserMentionsMarkdown(_ text: String, callback: (NSRange, URL) -> Void) {
   617→        // Define the regex pattern
   618→        let pattern = "\\[(.*?)\\]\\(https://matrix\\.to/#/(@.*?)\\)"
   619→        
   620→        // Create the regex
   621→        guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else {
   622→            return
   623→        }
   624→        
   625→        // Find matches in the input text
   626→        let nsText = text as NSString
   627→        let matches = regex.matches(in: text, options: [], range: NSRange(location: 0, length: nsText.length))
   628→        
   629→        // Process each match
   630→        for match in matches.sorted(by: { $0.range.length > $1.range.length }) {
   631→            // Extract the display name, user ID, and full URL
   632→            guard match.numberOfRanges == 3 else { continue }
   633→            
   634→            let userIDRange = match.range(at: 2)
   635→            let fullRange = match.range(at: 0)
   636→            
   637→            let userID = nsText.substring(with: userIDRange)
   638→            let fullURLString = "https://matrix.to/#/\(userID)"
   639→            
   640→            if let url = URL(string: fullURLString) {
   641→                callback(fullRange, url)
   642→            }
   643→        }
   644→    }
