## 5. MENTION UTILITIES AND DISPLAY TEXT

### Pill Display Formatting
**File:** `/Users/stjepandzojic/projects/element-x-ios/ElementX/Sources/Other/Pills/PillUtilities.swift`

```swift
enum PillUtilities {
    static let atRoom = "@room"
    static let composerAtRoomURLString = "#"  // Used by WYSIWYG to identify @room

    private static let userDecoration = "@"
    static func userPillDisplayText(username: String?, userID: String) -> String {
        guard let username else {
            return userID
        }
        return "\(userDecoration)\(username)"  // Displays as @username
    }

    private static let roomDecoration = "#"
    static func roomPillDisplayText(roomName: String?, rawRoomText: String) -> String {
        guard let roomName else {
            return rawRoomText
        }
        return "\(roomDecoration)\(roomName)"  // Displays as #roomname
    }
}
```

